#!/usr/bin/env python3
"""Prepare-only retained-source review for Batch 4; never connects to Supabase."""
from __future__ import annotations
import json, re, sys
from pathlib import Path
REPO=Path(__file__).resolve().parents[2]; sys.path.insert(0,str(REPO/'scripts'/'recipe-catalogue'))
import catalogue_core as cc  # noqa: E402
OUT=REPO/'output'/'recipe-batch4'; SOURCE=REPO/'output'/'recipe-extract'/'mindfulmocktail-recipes.jsonl'
IDS=('mm-hibiscus-electrolyte-drink','mm-fig-mocktail','mm-paloma-mocktails','mm-virgin-strawberry-daiquiri-margarita')
URLS={i:f'https://mindfulmocktail.com/{i[3:]}/' for i in IDS}; OTHER='__FRESH_UNRELATED_ROWS_AGGREGATE_HASH__'
REVIEWS={
 'mm-hibiscus-electrolyte-drink':{'ingredients':['1/2 cup chilled hibiscus tea','1/2 cup coconut water','Splash of pineapple juice to sweeten ((or to taste))','Pinch of mineral salt','Something to sweeten if you wish ((either more pineapple juice, honey, maple, your choice of sweetener))','Pineapple fronds, lime and/or hibiscus flowers ((optional garnishes))'],'flags':['ambiguous_ingredient_quantity_or_unit','unknown_quantity','source_classification_not_verified','template_preparation_needs_editorial_review'],'description':'Chilled hibiscus tea and coconut water over ice, brightened with pineapple and mineral salt.','steps':['Fill a glass with ice.','Pour in the chilled hibiscus tea and coconut water, then add pineapple juice and a pinch of mineral salt.','Add more pineapple juice or a sweetener of choice if wanted, then stir to combine.','Finish with optional pineapple fronds, lime, or hibiscus flowers and serve.'],'method':'build','garnish':'Pineapple fronds, lime, or hibiscus flowers (optional)','ice':'Ice','review':'The retained source is a one-glass pour-and-stir build; its pineapple and sweetener choices remain explicitly to taste/optional.'},
 'mm-fig-mocktail':{'ingredients':['1 ripe fresh fig ((plus extra for optional garnish))','1/2 tablespoon fig jam ((optional but does add a little extra flavor and mouthfeel))','1 oz lemon juice','2 oz apple cider','1/2 tablespoon grated ginger','1/2 oz cinnamon syrup ((can sub with a pinch of cinnamon powder, see Note 1))'],'flags':['ambiguous_ingredient_quantity_or_unit','unknown_unit','source_classification_not_verified','template_preparation_needs_editorial_review'],'description':'A still apple-and-fig drink with lemon, ginger, and cinnamon, served after shaking.','steps':['Cut the fresh fig into quarters and put it in a shaker with lemon juice, cinnamon syrup or its cinnamon alternative, and optional fig jam.','Use a muddler to break the fruit down well.','Combine the ginger, cider, and ice in the shaker, then shake with the lid on.','Fine strain into the serving glass; a piece of fig is an optional finish.'],'method':'shake','garnish':'Fresh fig (optional)','ice':'Ice','review':'The source calls this still and shakes only non-carbonated ingredients. Fig jam, cinnamon-powder substitution, and fig garnish remain optional/source-specific.'},
 'mm-paloma-mocktails':{'ingredients':['2 ounce grapefruit juice','1 ounce lime juice ((squeezed fresh is best))','1/2 ounce maple syrup ((or your choice of sweetener - see Note 1))','1/4 teaspoon apple cider vinegar ((or non-alcoholic tequila - see Note 2))','Pinch of sea salt','1/2 cup plain or grapefruit soda ((optional - see Note 3))','Salt or Tajin for rim ((optional))'],'flags':['ambiguous_ingredient_quantity_or_unit','carbonation_plus_shake','unknown_quantity','source_classification_not_verified','template_preparation_needs_editorial_review'],'description':'Grapefruit and lime with maple, salt and a sharp optional alternative, finished with optional soda.','steps':['Optionally rim a glass with salt or Tajín, then fill it with ice.','Shake the grapefruit juice, lime juice, maple syrup or another sweetener, apple cider vinegar or non-alcoholic tequila, and sea salt with ice until cold.','Strain into the prepared glass.','Top with the optional plain or grapefruit soda, stir gently, and serve.'],'method':'shake','garnish':None,'ice':'Ice','review':'The source separates shaking from the optional soda finish. The reviewed method never shakes carbonation; the optional rim is retained while no unsupported garnish is required.'}
}
EXCLUSION={'id':'mm-virgin-strawberry-daiquiri-margarita','decision':'exclude','reason':'BLOCKING source ambiguity: the optional ingredient permits “a couple of drops of bitters” without identifying a non-alcoholic product, while the record is classified mocktail/virgin. The source also directs a lime garnish although the retained ingredients supply only lime juice, and allows water adjustment although water is not listed. Those conflicts prevent safe, source-faithful publication; no flags are cleared and no DB/image write is authorized.'}
def clean(x): return cc.clean_text(str(x))
def sql(x): return "'"+x.replace("'","''")+"'"
def arr(v): return 'ARRAY['+','.join(sql(x) for x in v)+']::text[]'
def j(v): return sql(json.dumps(v,ensure_ascii=False))+'::jsonb'
def run():
 records={json.loads(x)['source_url'].rstrip('/'):json.loads(x) for x in SOURCE.read_text(encoding='utf8').splitlines() if x.strip()}; evidence=[]; updates=[]; images=[]
 for i,r in REVIEWS.items():
  s=records.get(URLS[i].rstrip('/'))
  if not s or [clean(x) for x in s['recipeIngredient']]!=r['ingredients']: raise SystemExit(f'FAIL source/ingredient mismatch {i}')
  if r['method'] not in cc.METHODS or (r['method']=='shake' and re.search(r'\b(?:soda|ginger beer|ginger ale|cola)\b',' '.join(r['ingredients']),re.I) and i!='mm-paloma-mocktails'): raise SystemExit(f'FAIL unsafe method {i}')
  generated=cc.ngrams(r['description'])
  for step in r['steps']: generated|=cc.ngrams(step)
  sourcegrams=cc.ngrams(clean(s.get('description') or ''))|cc.ngrams(cc.instruction_text(s))
  if generated&sourcegrams: raise SystemExit(f'FAIL six-word source overlap {i}')
  image=clean(s['image'][0]) if s.get('image') else None
  if image and (not image.startswith('https://') or re.search(r'-\d+x\d+\.(?:jpg|jpeg|png|webp)$',image,re.I)): raise SystemExit(f'FAIL image {i}')
  evidence.append({'id':i,'decision':'publish','source_url':URLS[i],'source_ingredients':s['recipeIngredient'],'source_instructions':s['recipeInstructions'],'source_yield':s['recipeYield'],'source_prep_time':s.get('prepTime'),'allergens':None,'has_caffeine':None,'review':r['review'],'image':image,'image_note':'retained first full-size source image; not refetched'})
  updates.append({'id':i,'description':r['description'],'preparation':r['steps'],'preparation_method':r['method'],'garnish':r['garnish'],'ice_type':r['ice']}); images.append({'id':i,'image_url':image})
 s=records.get(URLS[EXCLUSION['id']].rstrip('/')); evidence.append({**EXCLUSION,'source_url':URLS[EXCLUSION['id']],'source_ingredients':s['recipeIngredient'],'source_instructions':s['recipeInstructions'],'status_kept':'draft','flags_kept':'live-verified before state'})
 OUT.mkdir(parents=True,exist_ok=True)
 for name,data in [('batch4-evidence.jsonl',''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in evidence)),('batch4-updates.jsonl',''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in updates)),('batch4-images.json',json.dumps({'rows':images,'excluded':EXCLUSION,'fallback':'SVG fallback if no authorized retained image'},indent=2)+'\n')]: (OUT/name).write_text(data,encoding='utf8')
 ids=', '.join(sql(x['id']) for x in updates); ph={x['id']:f'__FRESH_ROW_HASH:{x["id"]}__' for x in updates}; post={x['id']:f'__FRESH_POST_EDITORIAL_ROW_HASH:{x["id"]}__' for x in updates}
 guards='\n'.join(f"if (select md5(to_jsonb(d)::text) from public.drinks d where id={sql(i)}) <> {sql(ph[i])} then raise exception 'row drift {i}'; end if;" for i in ph)
 edits='\n'.join(f"update public.drinks set description={sql(x['description'])}, preparation={j(x['preparation'])}, preparation_method={sql(x['preparation_method'])}, garnish={'null' if x['garnish'] is None else sql(x['garnish'])}, ice_type={sql(x['ice_type'])}, status='published', editorial_ready=true, recipe_quality_issues='{{}}'::text[] where id={sql(x['id'])} and status='draft' and editorial_ready=false and featured=false and recipe_quality_issues={arr(REVIEWS[x['id']]['flags'])}; get diagnostics changed=row_count; if changed<>1 then raise exception 'editorial count {x['id']}'; end if;" for x in updates)
 (OUT/'batch4-editorial.sql').write_text(f"-- PREPARE ONLY; fresh placeholders required.\nbegin; do $$ declare changed integer; begin\n{guards}\nif (select md5(string_agg(md5(to_jsonb(d)::text),'' order by id)) from public.drinks d where id not in ({ids})) <> {sql(OTHER)} then raise exception 'unrelated drift'; end if;\n{edits}\nend $$; commit;\n",encoding='utf8')
 pguards='\n'.join(f"if (select md5(to_jsonb(d)::text) from public.drinks d where id={sql(i)}) <> {sql(post[i])} then raise exception 'post editorial drift {i}'; end if;" for i in post)
 iedits='\n'.join(f"update public.drinks set image_url={sql(x['image_url'])},image_alt=name where id={sql(x['id'])} and status='published' and editorial_ready and image_url is null and md5(to_jsonb(drinks)::text)={sql(post[x['id']])}; get diagnostics changed=row_count; if changed<>1 then raise exception 'image count {x['id']}'; end if;" for x in images)
 (OUT/'batch4-images.sql').write_text(f"-- PREPARE ONLY; fresh POST_EDITORIAL placeholders required.\nbegin; do $$ declare changed integer; begin\n{pguards}\nif (select md5(string_agg(md5(to_jsonb(d)::text),'' order by id)) from public.drinks d where id not in ({ids})) <> {sql(OTHER)} then raise exception 'unrelated drift'; end if;\n{iedits}\nend $$; commit;\n",encoding='utf8')
 print('PASS: 3 publish candidates + 1 explicit exclusion reviewed')
if __name__=='__main__': run()
